window.VCAD2 = window.VCAD2 || {};

window.VCAD2.BlenderExporter = {
  toPythonScript(assembly, joints) {
    const lines = [
      '# Auto-generated by GiveGigs Valley CAD 2 (ldraw-mecha + GPT 6 Luna Light)',
      'import bpy',
      'import math',
      '',
      `# Assembly: ${assembly.name || 'Model'}`,
      'bpy.ops.object.select_all(action="SELECT")',
      'bpy.ops.object.delete(use_global=False)',
      ''
    ];

    (assembly.parts || []).forEach(p => {
      lines.push(`# Part ${p.id} (${p.type}) [${p.submodel}]`);
      lines.push(`bpy.ops.mesh.primitive_cube_add(location=(${p.pos[0]}, ${p.pos[2]}, ${p.pos[1]}))`);
      lines.push(`obj = bpy.context.active_object`);
      lines.push(`obj.name = "${p.id}"`);
    });

    lines.push('', '# Kinematic Drivers (ldraw-mecha)');
    (joints || []).forEach(j => {
      lines.push(`# Joint ${j.partId}: ${j.type} | axis=${j.axis} | ratio=${j.ratio}`);
      lines.push(`if "${j.partId}" in bpy.data.objects:`);
      lines.push(`    drv = bpy.data.objects["${j.partId}"].driver_add("rotation_euler", 2).driver`);
      lines.push(`    drv.expression = f"frame * 0.05 * ${j.ratio}"`);
    });

    return lines.join('\n');
  }
};
